//유저 레벨에 드는 경험치. 한 칸이 한 레벨이다.
//
//두 점을 지나게 뽑았다.
//
//    레벨 1     첫 소보스 하나 (경험치 40)
//    레벨 97-98 그 구간 잡몹 100 마리
//
//예전 표는 4 에서 500,000 까지 12만 5천 배로 올랐다. 그런데 잡몹이 주는
//경험치는 체력 곡선을 따라 527 배로만 오른다(스테이지 0 에서 20,000 까지).
//두 곡선의 기울기가 이렇게 다르면 어디선가 반드시 엇갈린다. 실제로
//첫 소보스 하나에 3 레벨이 오르고, 97 레벨에는 1,370 마리가 필요했다.
//
//그래서 표를 진행 속도에서 역산했다. 등비 1.0314 다. 이 값으로 첫 소보스가
//정확히 한 레벨이고, 97 레벨 구간이 백 마리다. 99 레벨은 전투 1,405 판
//(스테이지 281) 즈음이다.
//
//유저 레벨이 일찍 끝나는 것은 뜻이 있다. 체력에서 레벨 몫은 셋이고 장비가
//일곱이다(HERO_HP_PER_LEVEL / HERO_HP_PER_ARMOR). 레벨이 바닥을 깔고 나면
//그 뒤는 장비가 끌고 간다.
//
//칸 수를 바꾸면 Def.h 의 MAXUSERLEVEL 도 같이 바꾼다. NextExp() 가 표
//크기로 자르므로 터지지는 않지만, 그 위 레벨은 조용히 같은 값을 쓴다.
